/**************************************************************************/
/*                                                                        */
/*  BOARD SUPPORT                                          RELEASE        */
/*                                                                        */
/*    linflexd.c                                       Cortex-R52/GNU     */
/*                                                           6.5.2        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Frédéric Desbiens, Eclipse Foundation                               */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    Polled console on LINFlex_9, which is the instance wired to the     */
/*    S32Z280-594EVB daughtercard USB-UART through jumper J248.  Not      */
/*    LINFlex_0: that is simply the first instance in the Reference       */
/*    Manual's list and reaches no connector on this board.               */
/*                                                                        */
/*  BAUD RATE                                                             */
/*                                                                        */
/*    LINFlex_9 is clocked by P5_LIN_BAUD_CLK, which MC_CGM_5 MUX 2       */
/*    drives.  Read from the board: MUX_2_CSS selects source 2 with the   */
/*    divider set to 1, and the EVB carries a 40 MHz crystal (UG10268     */
/*    section 3.3.1.1), so the clock is 40 MHz.                           */
/*                                                                        */
/*        LFDIV   = 40000000 / (16 * 115200) = 21.7014                    */
/*        LINIBRR = 21                                                    */
/*        LINFBRR = round(0.7014 * 16) = 11                               */
/*        actual  = 40000000 / (16 * 21.6875) = 115274 baud, 0.06% error  */
/*                                                                        */
/*    Those are exactly the values the BootROM had already left in the    */
/*    registers, which is what confirms the 40 MHz figure rather than     */
/*    merely assuming it.  They are programmed here anyway: inheriting    */
/*    another program's register state makes this image's behaviour       */
/*    depend on how the board was last booted.                            */
/*                                                                        */
/*    The BootROM's configuration is NOT reused for a second reason: it   */
/*    leaves PCE set (parity enabled) and TxEn clear, because it is       */
/*    listening for a serial-boot download rather than printing.  A host  */
/*    terminal set to 8N1 against that would show framing errors.         */
/*                                                                        */
/*  MISRA C:2012 deviations (justified)                                   */
/*                                                                        */
/*    Rule 11.4/11.6 -- casting integer addresses to volatile pointers is */
/*      inherent to memory-mapped device access; confined to REG32.       */
/*                                                                        */
/**************************************************************************/

#include "linflexd.h"
#include "platform.h"

#define REG32(address)          (*(volatile unsigned int *)(address))

/* Register offsets, from the S32Z2 Reference Manual section 75.5.1.      */

#define LINFLEXD_LINCR1         0x00U
#define LINFLEXD_LINSR          0x08U
#define LINFLEXD_UARTCR         0x10U
#define LINFLEXD_UARTSR         0x14U
#define LINFLEXD_LINFBRR        0x24U
#define LINFLEXD_LINIBRR        0x28U
#define LINFLEXD_BDRL           0x38U

/* LINCR1                                                                 */
#define LINCR1_INIT             (1U << 0)       /* initialisation mode      */
#define LINCR1_SLEEP            (1U << 1)

/* UARTCR.  Bit positions verified against the register diagram; PCE at bit 2
   and TxEn at bit 4 are the two that matter here and are easy to transpose.  */
#define UARTCR_UART             (1U << 0)       /* UART rather than LIN mode */
#define UARTCR_WL0              (1U << 1)       /* with WL1 clear: 8-bit     */
#define UARTCR_PCE              (1U << 2)       /* parity enable             */
#define UARTCR_TXEN             (1U << 4)
#define UARTCR_RXEN             (1U << 5)

/* UARTSR                                                                 */
#define UARTSR_DTF              (1U << 1)       /* transmit complete, w1c    */

/* 115200 from a 40 MHz P5_LIN_BAUD_CLK; see the file header.             */
#define LINFLEXD_IBRR_115200    21U
#define LINFLEXD_FBRR_115200    11U

#define CONSOLE_BASE            S32Z_LINFLEX_9_BASE


void linflexd_init(void)
{
    /* Enter initialisation mode: the baud and mode registers are writable
       only there.  SLEEP is cleared at the same time, since the BootROM may
       have left the module asleep.  */

    REG32(CONSOLE_BASE + LINFLEXD_LINCR1) = LINCR1_INIT;

    /* The UART bit gates writes to the rest of UARTCR, so it has to be set
       before the fields that depend on it, not alongside them.  */

    REG32(CONSOLE_BASE + LINFLEXD_UARTCR) = UARTCR_UART;

    /* 8N1, transmit and receive.  PCE deliberately left clear: the BootROM
       enables parity for serial boot, and a host on 8N1 would see framing
       errors.  */

    REG32(CONSOLE_BASE + LINFLEXD_UARTCR) = UARTCR_UART | UARTCR_WL0
                                          | UARTCR_TXEN | UARTCR_RXEN;

    REG32(CONSOLE_BASE + LINFLEXD_LINFBRR) = LINFLEXD_FBRR_115200;
    REG32(CONSOLE_BASE + LINFLEXD_LINIBRR) = LINFLEXD_IBRR_115200;

    /* Leave initialisation mode; the module starts operating.  */

    REG32(CONSOLE_BASE + LINFLEXD_LINCR1) = 0U;
}


void linflexd_putc(char c)
{
    if (c == '\n')
    {
        linflexd_putc('\r');
    }

    REG32(CONSOLE_BASE + LINFLEXD_BDRL) = (unsigned int)(unsigned char)c;

    /* Wait for the byte to be sent, then clear the flag by writing one to it.
       Polled on purpose: this console runs before any interrupt controller is
       configured, and it must work inside a fault handler.  */

    while ((REG32(CONSOLE_BASE + LINFLEXD_UARTSR) & UARTSR_DTF) == 0U)
    {
        /* wait */
    }

    REG32(CONSOLE_BASE + LINFLEXD_UARTSR) = UARTSR_DTF;
}


void linflexd_puts(const char *string)
{
    const char *p = string;

    if (p != (const char *)0)
    {
        while (*p != '\0')
        {
            linflexd_putc(*p);
            p++;
        }
    }
}


void linflexd_put_hex32(unsigned int value)
{
    static const char digits[] = "0123456789ABCDEF";
    unsigned int      shift    = 32U;

    while (shift > 0U)
    {
        shift -= 4U;
        linflexd_putc(digits[(value >> shift) & 0xFU]);
    }
}
